// ─── File: DiscoveryDemo.java ───
// Shows the difference: ServiceRegistry (the store) vs Service Discovery (the lookup).
package com.bank.discovery.demo;

import java.util.logging.*;

public class DiscoveryDemo {
    private static final Logger log = Logger.getLogger("Discovery");
    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setLevel(Level.ALL); h.setFormatter(new DsLogFormatter());
        log.addHandler(h); log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // The REGISTRY: the authoritative live list of instances.
        ServiceRegistry registry = new ServiceRegistry(30_000); // 30s lease
        registry.register(new ServiceInstance("payment-service", "pay-1", "10.0.0.11:8090"));
        registry.register(new ServiceInstance("payment-service", "pay-2", "10.0.0.12:8090"));
        registry.register(new ServiceInstance("payment-service", "pay-3", "10.0.0.13:8090"));

        // DISCOVERY: the process of resolving a name to a healthy instance.
        DiscoveryClient discovery = new DiscoveryClient(registry);
        AccountService account = new AccountService(discovery);

        log.info("=== All 3 instances healthy — discovery round-robins ===");
        for (int i = 0; i < 4; i++) account.callPayment("SAV2001");

        log.info("=== pay-2 crashes: stops heartbeating → registry prunes it ===");
        // pay-1 and pay-3 keep heartbeating; pay-2 does not.
        registry.heartbeat("payment-service", "pay-1");
        registry.heartbeat("payment-service", "pay-3");
        registry.expireFor("payment-service", "pay-2");  // simulate lease expiry
        registry.prune();

        log.info("=== Discovery now only returns the survivors ===");
        for (int i = 0; i < 4; i++) account.callPayment("SAV2001");

        log.info("=== A new instance pay-4 scales up and registers ===");
        registry.register(new ServiceInstance("payment-service", "pay-4", "10.0.0.14:8090"));
        for (int i = 0; i < 3; i++) account.callPayment("SAV2001");
    }
}

// ─── Would be in registry/ServiceInstance.java ───
class ServiceInstance {
    final String serviceName; final String instanceId; final String address;
    volatile long lastHeartbeat; volatile boolean up;
    ServiceInstance(String serviceName, String instanceId, String address) {
        this.serviceName = serviceName; this.instanceId = instanceId; this.address = address;
        this.lastHeartbeat = System.currentTimeMillis(); this.up = true;
    }
}

// ─── Would be in registry/ServiceRegistry.java (THE STORE) ───
class ServiceRegistry {
    private static final Logger log = Logger.getLogger("Discovery");
    // serviceName → (instanceId → instance): the authoritative live directory.
    private final java.util.Map<String, java.util.Map<String, ServiceInstance>> store = new java.util.concurrent.ConcurrentHashMap<>();
    private final long leaseMs;
    ServiceRegistry(long leaseMs) { this.leaseMs = leaseMs; }

    void register(ServiceInstance inst) {
        store.computeIfAbsent(inst.serviceName, k -> new java.util.concurrent.ConcurrentHashMap<>())
             .put(inst.instanceId, inst);
        log.info(() -> "REGISTER " + inst.serviceName + "/" + inst.instanceId + " @ " + inst.address);
    }
    void heartbeat(String service, String instanceId) {
        ServiceInstance i = get(service, instanceId);
        if (i != null) i.lastHeartbeat = System.currentTimeMillis();
    }
    void expireFor(String service, String instanceId) { // test helper: simulate missed heartbeats
        ServiceInstance i = get(service, instanceId);
        if (i != null) i.lastHeartbeat = System.currentTimeMillis() - (leaseMs + 1);
    }
    void deregister(String service, String instanceId) {
        java.util.Map<String, ServiceInstance> m = store.get(service);
        if (m != null) m.remove(instanceId);
    }
    // Prune instances whose lease (heartbeat) has expired — keeps the directory accurate.
    void prune() {
        long now = System.currentTimeMillis();
        store.values().forEach(m -> m.values().removeIf(i -> {
            boolean dead = now - i.lastHeartbeat > leaseMs;
            if (dead) log.warning(() -> "PRUNE dead instance " + i.serviceName + "/" + i.instanceId);
            return dead;
        }));
    }
    // Discovery queries THIS to get the current healthy instances.
    java.util.List<ServiceInstance> healthyInstances(String service) {
        java.util.Map<String, ServiceInstance> m = store.getOrDefault(service, java.util.Map.of());
        java.util.List<ServiceInstance> out = new java.util.ArrayList<>();
        for (ServiceInstance i : m.values()) if (i.up) out.add(i);
        return out;
    }
    private ServiceInstance get(String s, String id) {
        return store.getOrDefault(s, java.util.Map.of()).get(id);
    }
}

// ─── Would be in discovery/DiscoveryClient.java (THE LOOKUP PROCESS) ───
class DiscoveryClient {
    private static final Logger log = Logger.getLogger("Discovery");
    private final ServiceRegistry registry;             // discovery CONSUMES the registry
    private final java.util.concurrent.atomic.AtomicInteger rr = new java.util.concurrent.atomic.AtomicInteger();
    DiscoveryClient(ServiceRegistry registry) { this.registry = registry; }

    // Resolve a logical service name to ONE healthy instance (client-side load balancing).
    ServiceInstance discover(String serviceName) {
        java.util.List<ServiceInstance> instances = registry.healthyInstances(serviceName);
        if (instances.isEmpty()) throw new IllegalStateException("No healthy instances of " + serviceName);
        int idx = Math.abs(rr.getAndIncrement() % instances.size()); // round-robin
        return instances.get(idx);
    }
}

// ─── Would be in service/AccountService.java ───
class AccountService {
    private static final Logger log = Logger.getLogger("Discovery");
    private final DiscoveryClient discovery;
    AccountService(DiscoveryClient discovery) { this.discovery = discovery; }
    void callPayment(String accountId) {
        // "lb://payment-service" in Spring Cloud triggers exactly this discovery + pick.
        ServiceInstance instance = discovery.discover("payment-service");
        log.info(() -> "discovered payment-service → " + instance.instanceId + " @ " + instance.address
                + " → calling for " + accountId);
    }
}

// ─── Would be in DsLogFormatter.java ───
class DsLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
